mapper.select:
SELECT COUNT(*)
FROM place_groups
WHERE id = #{placeGroupId}

mapper.update:
UPDATE pois
SET
  map_x = #{mapX},
  map_y = #{mapY},
  longitude = #{longitude},
  latitude = #{latitude}
WHERE id = #{id}
  AND place_group_id = #{placeGroupId}
  AND status = 1
  AND COALESCE(area_code, '') != 'route'

mapper.delete:
DELETE e
FROM route_edges e
JOIN pois fp ON fp.id = e.from_poi_id
JOIN pois tp ON tp.id = e.to_poi_id
WHERE fp.place_group_id = #{placeGroupId}
  AND tp.place_group_id = #{placeGroupId}

DELETE FROM pois
WHERE place_group_id = #{placeGroupId}
  AND area_code = 'route'

mapper.update:
UPDATE pois
SET status = 0
WHERE id = #{poiId}
  AND place_group_id = #{placeGroupId}
  AND status = 1
  AND COALESCE(area_code, '') != 'route'

UPDATE spots
SET representative_poi_id = NULL
WHERE representative_poi_id = #{poiId}

mapper.select:
SELECT COALESCE(MAX(version_no), 0) + 1
FROM route_graph_versions
WHERE place_group_id = #{placeGroupId}

mapper.sql:
p.place_group_id = #{placeGroupId}
AND p.status = 1
AND COALESCE(p.area_code, '') NOT IN ('route', 'campus_summary', 'spot_summary')
